contracts.hb.v1:
# core §7.5's heartbeat: a revision with four collections, three resources
# that are none (a horizon of 0, none at all, and a stream's), and one
# collection of each shape.
[interface]
name  = "hb"
major = 1
minor = 0
uses  = ["freshness.v1"]

[resources.link]                     # one member
kind        = "state"
type        = { raw = "text/plain" }
annotations = { "freshness.ttl_s" = 60 }

[resources."peer/{peer}"]            # templated: at most 5 live, 3 bits
kind        = "state"
type        = { raw = "text/plain" }
params      = { peer = "string" }
cardinality = 5
annotations = { "freshness.ttl_s" = 60 }

[resources."route/{dest}"]           # @state, first in order: at most 2 live, 2 bits
kind        = "state"
explicit    = true
type        = { raw = "text/plain" }
params      = { dest = "string" }
cardinality = 2
annotations = { "freshness.ttl_s" = 300 }

[resources."sdu/{sdu}"]              # no ceiling: 32 bits
kind        = "state"
type        = { raw = "text/plain" }
params      = { sdu = "string" }
cardinality = "unbounded"
annotations = { "freshness.ttl_s" = 120 }

[resources.mode]                     # never stale: no collection
kind        = "state"
type        = { raw = "text/plain" }
annotations = { "freshness.ttl_s" = 0 }

[resources.note]                     # no horizon: no collection
kind = "state"
type = { raw = "text/plain" }

[resources.level]                    # a stream confirms by sampling: no collection
kind        = "stream"
type        = { raw = "text/plain" }
annotations = { "freshness.ttl_s" = 60 }

contracts.mixed.v1:
# core §7.5's owner heartbeat: a revision whose collections are of two
# exposures, so freshness.v2 §2.4 puts them in two owner heartbeats.
[interface]
name  = "mixed"
major = 1
minor = 0
uses  = ["freshness.v2", "link.v1"]

[resources."peer/{peer}"]            # host: at most 8 live, 4 bits
kind        = "state"
type        = { raw = "text/plain" }
params      = { peer = "string" }
cardinality = 8
annotations = { "freshness.ttl_s" = 120 }

[resources.status]                   # link
kind        = "state"
type        = { raw = "text/plain" }
annotations = { "freshness.ttl_s" = 60, "link.exposure" = "link" }

[resources.uplink]                   # link
kind        = "state"
type        = { raw = "text/plain" }
annotations = { "freshness.ttl_s" = 300, "link.exposure" = "link" }
